<script setup>defineProps({ page: Number, total: Number, size: { type: Number, default: 10 } }); defineEmits(['update:page'])</script><template><div class="pagination"><span>{{ total ? (page-1)*size+1 : 0 }}–{{ Math.min(page*size,total) }} dari {{ total }} data</span><div><button class="icon-button" :disabled="page <= 1" aria-label="Halaman sebelumnya" @click="$emit('update:page',page-1)"><UiIcon name="left" :size="17" /></button><span class="page-number">{{ page }}</span><button class="icon-button" :disabled="page*size >= total" aria-label="Halaman berikutnya" @click="$emit('update:page',page+1)"><UiIcon name="right" :size="17" /></button></div></div></template>